	if len(qr.Series) != 1 || qr.Series[0].Count != 1 || qr.Series[0].Average != 2 {
		t.Fatalf("query after rollback = %+v, want count=1 average=2", qr.Series)
	}
}

// 查询路径：标签键在合法字符串值之后再次出现时，第二次值的类型不得掩盖重复；
