	// 失败查询不改变存储，标签子集查询照常命中原来的一个点。
	qr := mustQuery(t, store, `{"op":"query","name":"cpu","start":0,"end":2000,"labels":{"host":"a"}}`)
	if len(qr.Series) != 1 || qr.Series[0].Count != 1 || qr.Series[0].Average != 2 {
