func TestDuplicateLabelKeyDoesNotReplaceWholeLineFailure(t *testing.T) {
	eh := jsonHexKey("host")
	cases := []struct {
		name string
		line string
		want string
	}{
		// 数组残缺未闭合：标签对象内第二次值是数字。
		{"truncated write array",
			`[{"name":"m","timestamp":1,"value":1,"labels":{"host":"a","host":7}}`,
			"invalid JSON"},
		// 查询对象残缺未闭合：标签对象内第二次值是对象。
